struct MessageBuilder {
  typedef Message Table;
  ::flatbuffers::FlatBufferBuilder &fbb_;
  ::flatbuffers::uoffset_t start_;
  void add_type(slate::ipc::MessageType type) {
    fbb_.AddElement<int8_t>(Message::VT_TYPE, static_cast<int8_t>(type), 0);
  }
  void add_body_type(slate::ipc::MessageBody body_type) {
    fbb_.AddElement<uint8_t>(Message::VT_BODY_TYPE, static_cast<uint8_t>(body_type), 0);
  }
  void add_body(::flatbuffers::Offset<void> body) {
    fbb_.AddOffset(Message::VT_BODY, body);
  }
  explicit MessageBuilder(::flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ::flatbuffers::Offset<Message> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<Message>(end);
    return o;
  }
};

inline ::flatbuffers::Offset<Message> CreateMessage(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    slate::ipc::MessageType type = slate::ipc::MessageType_ExecuteCommand,
    slate::ipc::MessageBody body_type = slate::ipc::MessageBody_NONE,
    ::flatbuffers::Offset<void> body = 0) {
  MessageBuilder builder_(_fbb);
  builder_.add_body(body);
  builder_.add_body_type(body_type);
  builder_.add_type(type);
  return builder_.Finish();
}

inline bool VerifyMessageBody(::flatbuffers::Verifier &verifier, const void *obj, MessageBody type) {
  switch (type) {
    case MessageBody_NONE: {
      return true;
    }
    case MessageBody_ExecuteCommandMsg: {
      auto ptr = reinterpret_cast<const slate::ipc::ExecuteCommandMsg *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageBody_CommandOutputMsg: {
      auto ptr = reinterpret_cast<const slate::ipc::CommandOutputMsg *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageBody_CommandCompleteMsg: {
      auto ptr = reinterpret_cast<const slate::ipc::CommandCompleteMsg *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageBody_EnvSnapshotMsg: {
      auto ptr = reinterpret_cast<const slate::ipc::EnvSnapshotMsg *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageBody_ShutdownMsg: {
      auto ptr = reinterpret_cast<const slate::ipc::ShutdownMsg *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageBody_HeartbeatMsg: {
      auto ptr = reinterpret_cast<const slate::ipc::HeartbeatMsg *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageBody_ErrorMsg: {
      auto ptr = reinterpret_cast<const slate::ipc::ErrorMsg *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyMessageBodyVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyMessageBody(
        verifier,  values->Get(i), types->GetEnum<MessageBody>(i))) {
      return false;
    }
  }
  return true;
}

